#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    std::vector<long long> res(n, -1);
    std::vector<int> stk;
    for (int i = 0; i < n; ++i) {
        while (!stk.empty() && a[stk.back()] < a[i]) {
            res[stk.back()] = a[i];
            stk.pop_back();
        }
        stk.push_back(i);
    }
    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        printf("%lld", res[i]);
    }
    printf("\n");
    return 0;
}
